"""Four subgroup searches. Each breadth-first search runs from both ends."""

from functools import cache
from itertools import permutations

from cube import MOVES, SOLVED, apply_moves, inverse, read_state

HALF_TURNS = tuple(m for m in MOVES if m.endswith("2"))


@cache
def corner_classes():
    # Compute the corner permutations generated by half turns, then partition
    # all corner arrangements by relabeling pieces with those permutations.
    # A face turn permutes positions, so it commutes with this relabeling.
    group = {SOLVED.corners}
    stack = [SOLVED.corners]
    while stack:
        perm = stack.pop()
        for move in HALF_TURNS:
            neighbor = MOVES[move].take_corners(perm)
            if neighbor not in group:
                group.add(neighbor)
                stack.append(neighbor)

    classes = {}
    for perm in permutations(SOLVED.corners):
        if perm in classes:
            continue
        for relabel in group:
            classes[tuple(relabel[piece] for piece in perm)] = perm
    return classes


def slice_and_twists(cube):
    return cube.twists, tuple(edge >= 8 for edge in cube.edges)


def half_turn_class(cube):
    # By this phase the middle slice is already correct. Among the other
    # eight positions, the even-numbered edge pieces form one half-turn orbit.
    return corner_classes()[cube.corners], tuple(edge % 2 for edge in cube.edges[:8])


PHASES = (
    ("Orient edges", tuple(MOVES), lambda cube: cube.flips),
    ("Orient corners and place middle-slice edges",
     tuple(m for m in MOVES if m[0] not in "FB" or m.endswith("2")), slice_and_twists),
    ("Enter the half-turn subgroup",
     tuple(m for m in MOVES if m[0] in "UD" or m.endswith("2")), half_turn_class),
    ("Solve with half turns", HALF_TURNS, lambda cube: cube),
)


def path_from_root(parents, meeting):
    moves = []
    while parents[meeting] is not None:
        meeting, move = parents[meeting]
        moves.append(move)
    return moves[::-1]


def phase_path(state, moves, coordinate):
    start, goal = coordinate(state), coordinate(SOLVED)
    if start == goal:
        return []
    # Store only one representative per coordinate. Equivalent states always
    # have equivalent successors under the moves permitted in this phase.
    frontiers = [[(start, state)], [(goal, SOLVED)]]
    parents = [{start: None}, {goal: None}]
    while all(frontiers):
        side = int(len(frontiers[1]) < len(frontiers[0]))
        own, opposite = parents[side], parents[1 - side]
        next_layer = []
        for parent_key, representative in frontiers[side]:
            for move in moves:
                successor = MOVES[move](representative)
                key = coordinate(successor)
                if key in own:
                    continue
                own[key] = (parent_key, move)
                if key in opposite:
                    left = path_from_root(parents[0], key)
                    right = path_from_root(parents[1], key)
                    return left + [inverse(m) for m in reversed(right)]
                next_layer.append((key, successor))
        frontiers[side] = next_layer
    raise RuntimeError("No path to the subgroup was found for this cube.")


def solve(state):
    """Return a list of (phase name, move list) and verify it on the input."""
    state = read_state(state._asdict())
    phases = []
    for name, moves, coordinate in PHASES:
        path = phase_path(state, moves, coordinate)
        state = apply_moves(state, path)
        if coordinate(state) != coordinate(SOLVED):
            raise RuntimeError(f"Replay failed during phase: {name}")
        phases.append((name, path))
    return phases


def final_moves(state, phases):
    """Combine adjacent turns of one face and replay the result from the input."""
    suffix = {1: "", 2: "2", 3: "'"}
    amount = {"": 1, "2": 2, "'": 3}
    turns = []
    for _, path in phases:
        for move in path:
            face, count = move[0], amount[move[1:]]
            if turns and turns[-1][0] == face:
                count = (turns.pop()[1] + count) % 4
            if count:
                turns.append((face, count))
    solution = [face + suffix[count] for face, count in turns]
    if apply_moves(state, solution) != SOLVED:
        raise RuntimeError("Final solution failed replay on the original cube.")
    return solution
